// N8N-OPS-01: Initialize GitOps Guardian State
// EXTEND_EXISTING_INFRASTRUCTURE — extends existing Git repo + CLI export path.
// Prepares for daily drift detection between live n8n and Git repository.

const SCHEMA_VERSION = '1.0';
const PROJECT_ID = 'ghiw-n8n-ops-control-plane';
const REPO_IDENTITY = 'xxammaxx/n8n-blueprint-workflow';
const GIT_WORKFLOW_DIR = 'n8n/workflows/';

// Known GHIW workflows to monitor
const WATCHLIST = [
  '8kUOLhbvyeQSj6BO',  // GHIW-01 v2
  'zgjqWnTfjxOud1A5',  // GHIW-02 v1
  'Sv12QTo56NoPUu2D',  // DISPATCH
  '1qjUJa46S5l0RIHt',  // GHIW-01 legacy
  '88OuIcfW6TWgzkPa',  // Project Build Provisioning
  '9TlP8OFWZefNoynd'   // Lock Access Test
];

// Fields to strip during normalization (volatile, non-semantic)
const VOLATILE_FIELDS = ['updatedAt', 'versionId', 'activeVersionId', 'triggerCount', 'staticData', 'pinData', 'meta'];

// Fields that MUST NOT appear in exported workflows (secret patterns)
const SECRET_PATTERNS = [
  /api[_-]?key\s*[:=]\s*['"][A-Za-z0-9_-]{16,}['"]/i,
  /token\s*[:=]\s*['"][A-Za-z0-9_.-]{16,}['"]/i,
  /password\s*[:=]\s*['"][^'"]{3,}['"]/i,
  /ghp_[A-Za-z0-9]{36,}/,
  /-----BEGIN.*PRIVATE KEY-----/
];

const runId = 'w1-ops01-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);

const state = {
  schema_version: SCHEMA_VERSION,
  project_id: PROJECT_ID,
  run_id: runId,
  task_id: 'N8N-OPS-01',
  source: { type: 'schedule', id: new Date().toISOString() },
  workflow: { logical_id: 'N8N-OPS-01', id: $workflow.id, name: $workflow.name },
  execution: { id: $execution.id, started_at: new Date().toISOString() },
  state: 'INIT',
  watchlist: WATCHLIST,
  volatile_fields: VOLATILE_FIELDS,
  secret_patterns: SECRET_PATTERNS.map(p => p.source),
  repo_identity: REPO_IDENTITY,
  git_workflow_dir: GIT_WORKFLOW_DIR,
  live_workflows: {},
  git_workflows: {},
  drift_findings: [],
  secret_findings: [],
  timestamp: new Date().toISOString()
};

return [{ json: state }];

// N8N-OPS-01: Normalize & Sanitize Workflow Export
// Simulates CLI export → normalize volatile fields → scan for secrets → compute SHA256.
// In production: replaces simulated data with actual n8n CLI export via SSH.

const state = $input.first().json;

// Simulated live workflow exports (in production: from n8n export CLI)
// Using the rollback snapshot data for realistic testing
const simulatedExports = {
  '8kUOLhbvyeQSj6BO': {
    id: '8kUOLhbvyeQSj6BO',
    name: 'GHIW-01 v2 — Ensure Project Builder',
    active: false,
    nodes: [],
    connections: {},
    settings: { executionOrder: 'v1' },
    updatedAt: '2026-08-05T08:50:06.073Z',
    versionId: '2d4ab2e8-4ab3-474d-b96f-82c396c6019a',
    activeVersionId: null,
    versionCounter: 30
  },
  'zgjqWnTfjxOud1A5': {
    id: 'zgjqWnTfjxOud1A5',
    name: 'GHIW-02 v1 — GitHub Issue to Build Canary',
    active: false,
    nodes: [],
    connections: {},
    settings: { callerPolicy: 'workflowsFromSameOwner' },
    updatedAt: '2026-08-03T13:04:53.848Z',
    versionId: '7590b6b5-417d-49db-8f13-31e1f70270ad',
    versionCounter: 1
  }
};

function simpleHash(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
}

const secretFindings = [];
const driftFindings = [];
const liveWorkflows = {};

for (const wfId of state.watchlist) {
  const wf = simulatedExports[wfId] || null;

  if (!wf) {
    driftFindings.push({
      workflow_id: wfId,
      type: 'UNTRACKED_WORKFLOW',
      detail: 'Workflow exists in watchlist but not found in export'
    });
    continue;
  }

  // Step 1: Scan for secrets BEFORE normalization
  const wfStr = JSON.stringify(wf);
  for (const patternStr of state.secret_patterns) {
    const pattern = new RegExp(patternStr);
    if (pattern.test(wfStr)) {
      secretFindings.push({
        workflow_id: wfId,
        workflow_name: wf.name,
        pattern: patternStr.substring(0, 50),
        detail: 'SECRET_LEAK_BLOCKED — export blocked'
      });
      // DO NOT export this workflow
      continue;
    }
  }

  // Step 2: Normalize — strip volatile fields
  const normalized = JSON.parse(JSON.stringify(wf));
  for (const field of state.volatile_fields) {
    delete normalized[field];
  }

  // Step 3: Canonicalize — sort keys for deterministic serialization
  const canonical = JSON.parse(JSON.stringify(normalized, Object.keys(normalized).sort()));
  const canonicalStr = JSON.stringify(canonical);
  const hash = simpleHash(canonicalStr);

  liveWorkflows[wfId] = {
    id: wfId,
    name: wf.name,
    active: wf.active,
    node_count: (wf.nodes || []).length,
    canonical_sha256: hash,
    normalized: canonical
  };
}

state.live_workflows = liveWorkflows;
state.secret_findings = secretFindings;
state.drift_findings = driftFindings;
state.state = 'NORMALIZED';

// If secrets found, stop here
if (secretFindings.length > 0) {
  state.state = 'SECRET_LEAK_BLOCKED';
}

return [{ json: state }];

// N8N-OPS-01: Compare Live vs Git & Classify Drift
// Simulates comparison against Git repository baseline.
// Produces deterministic drift classification for each workflow.

const state = $input.first().json;

// If secrets were found, skip comparison
if (state.state === 'SECRET_LEAK_BLOCKED') {
  const output = {
    schema_version: state.schema_version,
    project_id: state.project_id,
    run_id: state.run_id,
    task_id: state.task_id,
    source: state.source,
    workflow: state.workflow,
    execution: { ...state.execution, completed_at: new Date().toISOString() },
    decision: 'SECRET_LEAK_BLOCKED',
    reason_codes: ['SECRET_PATTERN_DETECTED'],
    evidence_refs: [],
    classification: 'RED',
    timestamp: new Date().toISOString(),
    secret_findings: state.secret_findings
  };
  return [{ json: output }];
}

// Simulated Git baseline (in production: read from repo's n8n/workflows/)
const simulatedGitBaseline = {
  '8kUOLhbvyeQSj6BO': { sha256: 'c7ef85db0cb40b3e', modified: '2026-08-05' },
  'zgjqWnTfjxOud1A5': { sha256: '6d2eeb97870f4b8c', modified: '2026-08-03' }
};

const driftFindings = [];
const allWorkflowIds = new Set([
  ...Object.keys(state.live_workflows),
  ...Object.keys(simulatedGitBaseline)
]);

for (const wfId of allWorkflowIds) {
  const live = state.live_workflows[wfId];
  const git = simulatedGitBaseline[wfId];

  if (live && !git) {
    driftFindings.push({
      workflow_id: wfId,
      name: live.name,
      type: 'UNTRACKED_WORKFLOW',
      detail: 'Workflow exists live but not in Git'
    });
  } else if (!live && git) {
    driftFindings.push({
      workflow_id: wfId,
      type: 'DELETED_LIVE',
      detail: 'Workflow exists in Git but not live'
    });
  } else if (live && git) {
    if (live.canonical_sha256.substring(0, 16) !== git.sha256) {
      driftFindings.push({
        workflow_id: wfId,
        name: live.name,
        type: 'LIVE_DRIFT',
        live_sha256: live.canonical_sha256,
        git_sha256: git.sha256,
        detail: 'Live workflow hash differs from Git baseline'
      });
    } else {
      driftFindings.push({
        workflow_id: wfId,
        name: live.name,
        type: 'IN_SYNC',
        detail: 'Live matches Git baseline'
      });
    }
  }
}

// Determine overall decision
let decision = 'IN_SYNC';
let reasonCodes = ['LIVE_MATCHES_GIT'];
const driftTypes = driftFindings.filter(f => f.type !== 'IN_SYNC').map(f => f.type);

if (driftTypes.length === 0) {
  decision = 'IN_SYNC';
  reasonCodes = ['LIVE_MATCHES_GIT'];
} else if (driftTypes.includes('LIVE_DRIFT')) {
  decision = 'LIVE_DRIFT';
  reasonCodes = ['LIVE_AHEAD_OF_GIT', 'HASH_MISMATCH_DETECTED'];
} else if (driftTypes.includes('UNTRACKED_WORKFLOW')) {
  decision = 'UNTRACKED_WORKFLOW';
  reasonCodes = ['WORKFLOW_ONLY_LIVE'];
} else if (driftTypes.includes('DELETED_LIVE')) {
  decision = 'DELETED_LIVE';
  reasonCodes = ['WORKFLOW_ONLY_GIT'];
}

// Build output envelope
const output = {
  schema_version: state.schema_version,
  project_id: state.project_id,
  run_id: state.run_id,
  task_id: state.task_id,
  source: state.source,
  workflow: state.workflow,
  execution: { ...state.execution, completed_at: new Date().toISOString() },
  decision: decision,
  reason_codes: reasonCodes,
  evidence_refs: [],
  classification: decision === 'IN_SYNC' ? 'GREEN' : 'AMBER',
  timestamp: new Date().toISOString(),
  guardian_details: {
    workflows_checked: allWorkflowIds.size,
    in_sync: driftFindings.filter(f => f.type === 'IN_SYNC').length,
    drift_detected: driftTypes.length,
    drift_findings: driftFindings,
    secret_findings: state.secret_findings
  }
};

return [{ json: output }];

